def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    # Count how many numbers have each bit set.
    # nums[i] <= 10^9 < 2^30, so 30 bits are enough (0 to 29).
    bit_counts = [0] * 30
    for num in nums:
        for b in range(30):
            if num & (1 << b):
                bit_counts[b] += 1

    # We can put at most k copies of each bit into the chosen k elements.
    # To maximize the sum of squares, give the bits to the largest elements first.
    sums = [0] * k
    for b in range(30):
        c = bit_counts[b]
        if c > k:
            c = k
        val = 1 << b
        for i in range(c):
            sums[i] += val

    ans = 0
    for s in sums:
        ans = (ans + (s % MOD) * (s % MOD)) % MOD
    return ans
```

