from typing import List

def min_mountain_triplet_sum(nums: List[int]) -> int:
    """
    Returns the minimum possible sum of a mountain triplet (i, j, k) such that
    i < j < k, nums[i] < nums[j] and nums[k] < nums[j].
    If no such triplet exists, returns -1.
    """
    n = len(nums)
    min_sum = float('inf')

    # Check all triplets (i, j, k) with i < j < k
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if nums[i] < nums[j] and nums[k] < nums[j]:
                    current_sum = nums[i] + nums[j] + nums[k]
                    if current_sum < min_sum:
                        min_sum = current_sum

    return min_sum if min_sum != float('inf') else -1
```

