def min_operations(s1: str, s2: str, s3: str) -> int:
    # Find the length of the longest common prefix
    L = 0
    for c1, c2, c3 in zip(s1, s2, s3):
        if c1 == c2 == c3:
            L += 1
        else:
            break

    # If there is no common prefix, it's impossible to make them equal
    if L == 0:
        return -1

    # Total operations = (len(s1) - L) + (len(s2) - L) + (len(s3) - L)
    return len(s1) + len(s2) + len(s3) - 3 * L
```

