def countBeautifulSubstrings(s: str, k: int) -> int:
    vowels = set('aeiou')
    n = len(s)
    # prefix[i] will store the number of vowels in s[0:i]
    prefix = [0] * (n + 1)
    for i, ch in enumerate(s):
        prefix[i+1] = prefix[i] + (1 if ch in vowels else 0)

    beautiful_count = 0
    for i in range(n):
        for j in range(i+1, n+1):
            length = j - i
            # vowels == consonants implies length is even and vowels == length // 2
            if length % 2 == 1:
                continue
            v = prefix[j] - prefix[i]
            if v == length // 2:
                if (v * v) % k == 0:
                    beautiful_count += 1
    return beautiful_count
```

