def numberOfGoodPartitions(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Step 1: record the last occurrence index for each number
    last = {}
    for i, x in enumerate(nums):
        last[x] = i

    # Step 2: count how many "blocks" exist
    blocks = 0
    max_last = 0
    for i in range(n):
        max_last = max(max_last, last[nums[i]])
        if max_last == i:
            blocks += 1

    # Step 3: the number of good partitions is 2^(blocks - 1) % MOD
    return pow(2, blocks - 1, MOD)
```

