def countCompleteSubstrings(word: str, k: int) -> int:
    n = len(word)
    if k > n:
        return 0

    def process_segment(seg: str) -> int:
        L = len(seg)
        max_unique = min(26, L // k)
        total = 0

        for m in range(1, max_unique + 1):
            window_size = m * k
            if window_size > L:
                break

            count = [0] * 26
            valid = 0  # number of characters with count exactly k

            # Initialize first window
            for i in range(window_size):
                c = ord(seg[i]) - 97
                count[c] += 1
                if count[c] == k:
                    valid += 1
                elif count[c] == k + 1:
                    valid -= 1

            if valid == m:
                total += 1

            # Slide window
            for i in range(window_size, L):
                # Remove left character
                left_c = ord(seg[i - window_size]) - 97
                count[left_c] -= 1
                if count[left_c] == k:
                    valid += 1
                elif count[left_c] == k - 1:
                    valid -= 1

                # Add right character
                right_c = ord(seg[i]) - 97
                count[right_c] += 1
                if count[right_c] == k:
                    valid += 1
                elif count[right_c] == k + 1:
                    valid -= 1

                if valid == m:
                    total += 1

        return total

    ans = 0
    start = 0
    for i in range(n):
        # Check if current segment ends here
        if i == n - 1 or abs(ord(word[i + 1]) - ord(word[i])) > 2:
            ans += process_segment(word[start:i + 1])
            start = i + 1

    return ans
```

