from typing import List

def minCost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    INF = 10**18
    # dist[i][j] will store the minimum cost to change character i to character j
    dist = [[INF] * 26 for _ in range(26)]

    # Cost to change a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Initialize the graph with the given direct transformations
    for o, c, w in zip(original, changed, cost):
        u = ord(o) - 97
        v = ord(c) - 97
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        for i in range(26):
            if dist[i][k] == INF:
                continue
            for j in range(26):
                if dist[k][j] == INF:
                    continue
                new_dist = dist[i][k] + dist[k][j]
                if new_dist < dist[i][j]:
                    dist[i][j] = new_dist

    # Calculate the total minimum cost to convert source to target
    total_cost = 0
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue
        u = ord(s_char) - 97
        v = ord(t_char) - 97
        if dist[u][v] == INF:
            return -1
        total_cost += dist[u][v]

    return total_cost
```

