def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count(x: int) -> int:
        s_int = int(s)
        if x < s_int:
            return 0
        x_str = str(x)
        n = len(x_str)
        lenS = len(s)
        res = 0

        # numbers with length strictly less than n
        for L in range(lenS, n):
            prefix_len = L - lenS
            if prefix_len == 0:
                res += 1
            else:
                # first digit of prefix: 1..limit, remaining digits: 0..limit
                res += limit * ((limit + 1) ** (prefix_len - 1))

        # numbers with length exactly n
        prefix_len = n - lenS
        if prefix_len == 0:
            res += 1
        else:
            x_prefix = x_str[:prefix_len]
            x_suffix = x_str[prefix_len:]
            valid = True
            for i, ch in enumerate(x_prefix):
                d = int(ch)
                low = 1 if i == 0 else 0
                high = min(d - 1, limit)
                if low <= high:
                    rem = prefix_len - i - 1
                    res += (high - low + 1) * ((limit + 1) ** rem)
                if d < low or d > limit:
                    valid = False
                    break
            if valid and s <= x_suffix:
                res += 1
        return res

    return count(finish) - count(start - 1)
```

