from typing import List

def colorTheArray(n: int, queries: List[List[int]]) -> List[int]:
    nums = [0] * n
    pairs = 0
    ans = []
    for idx, color in queries:
        old = nums[idx]
        if old != color:
            # check left neighbor
            if idx > 0 and nums[idx - 1] != 0:
                if old == nums[idx - 1]:
                    pairs -= 1
                if color == nums[idx - 1]:
                    pairs += 1
            # check right neighbor
            if idx < n - 1 and nums[idx + 1] != 0:
                if old == nums[idx + 1]:
                    pairs -= 1
                if color == nums[idx + 1]:
                    pairs += 1
            nums[idx] = color
        ans.append(pairs)
    return ans
