def max_good_subarray_sum(nums, k):
    min_prefix = {}
    ans = float('-inf')
    p = 0
    for num in nums:
        # Check if current element can be the end of a good subarray
        target1 = num + k
        if target1 in min_prefix:
            # Subarray sum = (p + num) - min_prefix[target1]
            candidate = p + num - min_prefix[target1]
            if candidate > ans:
                ans = candidate
        target2 = num - k
        if target2 in min_prefix:
            candidate = p + num - min_prefix[target2]
            if candidate > ans:
                ans = candidate

        # Update min_prefix for the current element as a future start
        if num not in min_prefix or p < min_prefix[num]:
            min_prefix[num] = p

        p += num

    return 0 if ans == float('-inf') else ans
