def lastNonEmptyString(s: str) -> str:
    # Step 1: Count frequencies of each character
    freq = {}
    for c in s:
        freq[c] = freq.get(c, 0) + 1

    # Maximum frequency
    max_f = max(freq.values())

    # Step 2: Build the result by collecting the last occurrence 
    # of each character that has the maximum frequency.
    res = []
    count = {}
    for c in s:
        count[c] = count.get(c, 0) + 1
        # If this character is one of the max frequency characters
        # and we are at its last occurrence, add it.
        if freq[c] == max_f and count[c] == max_f:
            res.append(c)

    return ''.join(res)
