    for length, count in length_counts:
        needed_pairs_per_word = length // 2
        for _ in range(count):
            if total_pairs >= needed_pairs_per_word:
                total_pairs -= needed_pairs_per_word
                if length % 2 == 1:
                    if single_letters > 0:
                        single_letters -= 1
                    elif total_pairs > 0:
                        total_pairs -= 1
                        single_letters += 1
                    else:
                        continue
                max_palindromes += 1
            else:
                return max_palindromes

    return max_palindromes
