def longest_common_prefix(arr1: list[int], arr2: list[int]) -> int:
    # Store all possible prefixes of numbers in arr1
    prefixes = set()
    for num in arr1:
        s = str(num)
        for i in range(1, len(s) + 1):
            prefixes.add(s[:i])

    max_len = 0
    # For each number in arr2, check its prefixes from longest to shortest
    for num in arr2:
        s = str(num)
        for i in range(len(s), 0, -1):
            if s[:i] in prefixes:
                max_len = max(max_len, i)
                break  # longest prefix for this number found

    return max_len
