def punishment_number(n: int) -> int:
    def can_partition(s: str, target: int, index: int, current_sum: int) -> bool:
        # If we've reached the end of the string, check if the sum equals the target
        if index == len(s):
            return current_sum == target

        # Try all possible splits from the current index
        for j in range(index, len(s)):
            # Take substring s[index:j+1] as the next part
            part = int(s[index:j+1])
            # If adding this part already exceeds target, no need to check further
            # since all subsequent parts will be larger (positive integers)
            if current_sum + part > target:
                break
            # Recursively check the rest of the string
            if can_partition(s, target, j + 1, current_sum + part):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i, 0, 0):
            total += sq
    return total
