def solve():
    import sys
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    N = int(next(it))
    prereq = [[] for _ in range(N + 1)]
    dependents = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        C = int(next(it))
        for _ in range(C):
            p = int(next(it))
            prereq[i].append(p)
            dependents[p].append(i)

    # Find all books that must be read before book 1 (ancestors in dependency graph)
    required = set()
    stack = [1]
    visited = [False] * (N + 1)
    visited[1] = True
    while stack:
        u = stack.pop()
        if u != 1:
            required.add(u)
        for p in prereq[u]:
            if not visited[p]:
                visited[p] = True
                stack.append(p)

    # Kahn's topological sort on the required subgraph
    indeg = {u: 0 for u in required}
    for u in required:
        for p in prereq[u]:
            if p in required:
                indeg[u] += 1

    stack = [u for u in required if indeg[u] == 0]
    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in dependents[u]:
            if v in required:
                indeg[v] -= 1
                if indeg[v] == 0:
                    stack.append(v)

    print(' '.join(map(str, order)))
