import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    L = [int(next(it)) for _ in range(N)]

    # The minimum possible width is at least the maximum word length.
    low = max(L)
    # The maximum possible width is all words in a single line.
    high = sum(L) + N - 1

    def lines_needed(W: int) -> int:
        lines = 1
        current_width = 0
        for length in L:
            if current_width == 0:
                current_width = length
            else:
                if current_width + 1 + length <= W:
                    current_width += 1 + length
                else:
                    lines += 1
                    current_width = length
        return lines

    # Binary search for the minimal width such that lines_needed <= M.
    while low < high:
        mid = (low + high) // 2
        if lines_needed(mid) <= M:
            high = mid
        else:
            low = mid + 1

    print(low)
