def solve() -> None:
    import sys

    input = sys.stdin.readline
    N, M = map(int, input().split())

    adj = [[] for _ in range(N + 1)]
    max_ratio = 0.0
    for _ in range(M):
        u, v, b, c = map(int, input().split())
        adj[u].append((v, b, c))
        if c > 0:
            ratio = b / c
            if ratio > max_ratio:
                max_ratio = ratio

    def check(x: float) -> bool:
        dist = [-float('inf')] * (N + 1)
        dist[1] = 0.0
        for u in range(1, N + 1):
            du = dist[u]
            if du == -float('inf'):
                continue
            for v, b, c in adj[u]:
                w = b - x * c
                nd = du + w
                if nd > dist[v]:
                    dist[v] = nd
        return dist[N] >= 0.0

    lo = 0.0
    hi = max_ratio
    # 60 iterations are enough for 1e-9 precision
    for _ in range(60):
        mid = (lo + hi) * 0.5
        if check(mid):
            lo = mid
        else:
            hi = mid

    print(f"{lo:.15f}")
