    dp = [INF] * (K1 + 1)
    dp[0] = 0

    for d in D:
        new_dp = [INF] * (K1 + 1)
        for x in range(K1 + 1):
            # Minimum type-2 sensors needed if we use x type-1 sensors for this section
            rem = d - x * L1
            if rem <= 0:
                y = 0
            else:
                y = (rem + L2 - 1) // L2
            if y > K2:
                # Even if we use no type-2 elsewhere, we would exceed K2
                continue
            for used in range(K1 - x + 1):
                if dp[used] != INF:
                    new_y = dp[used] + y
                    if new_y < new_dp[used + x]:
                        new_dp[used + x] = new_y
        dp = new_dp

    ans = INF
    for j in range(K1 + 1):
        if dp[j] <= K2:
            cost = C1 * j + C2 * dp[j]
            if cost < ans:
                ans = cost

    if ans == INF:
        print(-1)
    else:
        print(ans)
