import sys
from itertools import combinations, permutations

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    R = input().strip()
    C = input().strip()

    # Precompute all valid rows for each possible leftmost character
    rows_by_left = {'A': [], 'B': [], 'C': []}
    for cols in combinations(range(N), 3):
        c1, c2, c3 = cols
        for left_char in ('A', 'B', 'C'):
            remaining = [c for c in ('A', 'B', 'C') if c != left_char]
            for perm in permutations(remaining):
                row = ['.'] * N
                row[c1] = left_char
                row[c2] = perm[0]
                row[c3] = perm[1]
                rows_by_left[left_char].append(''.join(row))

    col_counts = {ch: [0] * N for ch in 'ABC'}
    col_first = [None] * N
    grid = []

    def backtrack(r):
        if r == N:
            return True
        left_req = R[r]
        for row_str in rows_by_left[left_req]:
            ok = True
            first_set = []
            for c, ch in enumerate(row_str):
                if ch != '.':
                    if col_counts[ch][c] == 1:
                        ok = False
                        break
                    if col_first[c] is None:
                        if ch != C[c]:
                            ok = False
                            break
                        first_set.append(c)
            if not ok:
                continue

            # Place the row
            for c, ch in enumerate(row_str):
                if ch != '.':
                    col_counts[ch][c] += 1
            for c in first_set:
                col_first[c] = row_str[c]
            grid.append(row_str)

            if backtrack(r + 1):
                return True

            # Backtrack
            grid.pop()
            for c, ch in enumerate(row_str):
                if ch != '.':
                    col_counts[ch][c] -= 1
            for c in first_set:
                col_first[c] = None
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print(row)
    else:
        print("No")

if __name__ == "__main__":
    solve()
