from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2]
    T = data[3]

    K = N - M + 1
    bad_count = [0] * K
    covered = [False] * N
    q = deque()

    # Precompute mismatch counts for every interval of length M
    for l in range(K):
        cnt = 0
        for j in range(M):
            if S[l + j] != T[j]:
                cnt += 1
        bad_count[l] = cnt
        if cnt == 0:
            q.append(l)

    # Process intervals that can be "un-stamped"
    while q:
        l = q.popleft()
        # Skip if this interval is already completely covered
        all_covered = True
        for j in range(M):
            if not covered[l + j]:
                all_covered = False
                break
        if all_covered:
            continue

        # Apply the operation: cover all positions in this interval
        for j in range(M):
            i = l + j
            if not covered[i]:
                covered[i] = True
                # Update all intervals that contain position i
                start = max(0, i - M + 1)
                end = min(i, N - M)
                for l_prime in range(start, end + 1):
                    if S[i] != T[i - l_prime]:
                        bad_count[l_prime] -= 1
                        if bad_count[l_prime] == 0:
                            q.append(l_prime)

    if all(covered):
        print("Yes")
    else:
        print("No")
