from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    """
    Returns True if the graph where indices i and j are connected by an edge
    when gcd(nums[i], nums[j]) > 1 is fully connected (i.e., all pairs reachable).
    """
    n = len(nums)
    if n == 1:
        return True

    max_val = max(nums)
    # Smallest Prime Factor (SPF) sieve up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Disjoint Set Union (DSU) structures
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    first = {}  # maps a prime factor to the first index that contains it
    for i, num in enumerate(nums):
        x = num
        # factorize using SPF
        while x > 1:
            p = spf[x]
            while x % p == 0:
                x //= p
            if p in first:
                union(i, first[p])
            else:
                first[p] = i

    # Check if all indices belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
