def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    H = int(next(it))
    W = int(next(it))

    A = [[int(next(it)) for _ in range(W)] for _ in range(H)]
    B = [[int(next(it)) for _ in range(W)] for _ in range(H)]

    # Precompute inversion counts for all permutations of 0..H-1 and 0..W-1
    def inv_count(perm):
        # permutation as tuple of ints
        c = 0
        n = len(perm)
        for i in range(n):
            for j in range(i+1, n):
                if perm[i] > perm[j]:
                    c += 1
        return c

    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    row_inv = {p: inv_count(p) for p in row_perms}
    col_inv = {p: inv_count(p) for p in col_perms}

    min_ops = float('inf')

    for rp in row_perms:
        for cp in col_perms:
            # check if A[rp[i]][cp[j]] == B[i][j]
            ok = True
            for i in range(H):
                # Quick early break if possible: we can check row by row
                rowA = A[rp[i]]
                rowB = B[i]
                for j in range(W):
                    if rowA[cp[j]] != rowB[j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                ops = row_inv[rp] + col_inv[cp]
                if ops < min_ops:
                    min_ops = ops

    if min_ops == float('inf'):
        print(-1)
    else:
        print(min_ops)

if __name__ == "__main__":
