import math
from typing import List

class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        def first_digit(x: int) -> int:
            # x is positive and has no trailing zero, so this works
            while x >= 10:
                x //= 10
            return x

        n = len(nums)
        first_digits = [first_digit(num) for num in nums]
        last_digits = [num % 10 for num in nums]

        beautiful_pairs = 0
        for i in range(n):
            for j in range(i + 1, n):
                if math.gcd(first_digits[i], last_digits[j]) == 1:
                    beautiful_pairs += 1

        return beautiful_pairs
