import sys

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    INF = 10**18

    # distance matrix initialisation
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u, v, w = map(int, input().split())
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd-Warshall: all-pairs shortest paths
    for k in range(N):
        dk = dist[k]
        for i in range(N):
            di = dist[i]
            dik = di[k]
            if dik == INF:
                continue
            for j in range(N):
                dkj = dk[j]
                if dkj != INF:
                    new = dik + dkj
                    if new < di[j]:
                        di[j] = new

    # DP over subsets (bitmask) for minimum weight path visiting all vertices
    size = 1 << N
    dp = [[INF] * N for _ in range(size)]
    for i in range(N):
        dp[1 << i][i] = 0

    full_mask = size - 1
    for mask in range(1, size):
        for last in range(N):
            cost = dp[mask][last]
            if cost == INF:
                continue
            not_mask = full_mask ^ mask
            nxt = not_mask
            while nxt:
                bit = nxt & -nxt
                v = bit.bit_length() - 1
                nxt ^= bit
                if dist[last][v] == INF:
                    continue
                new_cost = cost + dist[last][v]
                new_mask = mask | bit
                if new_cost < dp[new_mask][v]:
                    dp[new_mask][v] = new_cost

    ans = min(dp[full_mask])
    if ans >= INF:
        print("No")
    else:
        print(ans)
