import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    Q = int(next(it))
    S = next(it).strip()

    # 1-indexed BIT for maintaining "bad" adjacent pairs.
    # a[i] = 1 if S[i] == S[i+1] (1-indexed for i = 1 .. N-1)
    bit = [0] * (N + 2)
    a = [0] * (N + 2)

    def bit_add(idx, delta):
        while idx <= N:
            bit[idx] += delta
            idx += idx & -idx

    def bit_sum(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    # Initialize BIT with pairs from S
    for i in range(1, N):
        if S[i - 1] == S[i]:
            a[i] = 1
            bit_add(i, 1)

    out_lines = []
    for _ in range(Q):
        typ = int(next(it))
        L = int(next(it))
        R = int(next(it))
        if typ == 1:
            # flip range [L, R] in S
            if L > 1:
                idx = L - 1
                if a[idx] == 1:
                    a[idx] = 0
                    bit_add(idx, -1)
                else:
                    a[idx] = 1
                    bit_add(idx, 1)
            if R < N:
                idx = R
                if a[idx] == 1:
                    a[idx] = 0
                    bit_add(idx, -1)
                else:
                    a[idx] = 1
                    bit_add(idx, 1)
        else:  # typ == 2
            if L == R:
                out_lines.append("Yes")
            else:
                total = bit_sum(R - 1) - bit_sum(L - 1)
                out_lines.append("Yes" if total == 0 else "No")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
