def solve():
    import sys

    input = sys.stdin.readline
    N = int(input().strip())
    A = list(map(int, input().split()))

    MAX_A = 200000

    # Smallest Prime Factor sieve up to MAX_A
    spf = list(range(MAX_A + 1))
    for i in range(2, int(MAX_A ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, MAX_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def square_free(x: int) -> int:
        """Return the square-free part of a positive integer x."""
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if cnt % 2 == 1:
                res *= p
        return res

    zero_cnt = 0
    freq = {}
    for val in A:
        if val == 0:
            zero_cnt += 1
        else:
            sf = square_free(val)
            freq[sf] = freq.get(sf, 0) + 1

    ans = zero_cnt * (N - zero_cnt) + zero_cnt * (zero_cnt - 1) // 2
    for cnt in freq.values():
        ans += cnt * (cnt - 1) // 2

    print(ans)
