import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))
    tiles = [(int(next(it)), int(next(it))) for _ in range(N)]

    # Early check on total available area
    total_area = sum(a * b for a, b in tiles)
    if total_area < H * W:
        print("No")
        return

    # Sort tiles by area descending to improve backtracking performance
    tiles.sort(key=lambda x: x[0] * x[1], reverse=True)

    # Precompute orientations for each tile
    oriented = []
    for a, b in tiles:
        if a == b:
            oriented.append(((a, b),))
        else:
            oriented.append(((a, b), (b, a)))

    grid = [[0] * W for _ in range(H)]
    used = [False] * N

    def backtrack() -> bool:
        # Find the first uncovered cell (top-leftmost)
        r = c = -1
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:          # All cells are covered
            return True

        for idx in range(N):
            if used[idx]:
                continue
            for w, h in oriented[idx]:
                if r + h > H or c + w > W:
                    continue
                # Check whether the rectangle is free
                ok = True
                for i in range(r, r + h):
                    for j in range(c, c + w):
                        if grid[i][j] == 1:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue

                # Place the tile
                for i in range(r, r + h):
                    for j in range(c, c + w):
                        grid[i][j] = 1
                used[idx] = True

                if backtrack():
                    return True

                # Remove the tile (backtrack)
                for i in range(r, r + h):
                    for j in range(c, c + w):
                        grid[i][j] = 0
                used[idx] = False

        return False

    print("Yes" if backtrack() else "No")

if __name__ == "__main__":
    solve()
