def solve():
    import sys
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    if not data:
        return
    A = list(map(int, data))
    # Precompute winning line masks (8 lines in 3x3 grid)
    lines = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),  # rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8),  # columns
        (0, 4, 8), (2, 4, 6)              # diagonals
    ]
    line_masks = []
    for line in lines:
        mask = 0
        for idx in line:
            mask |= (1 << idx)
        line_masks.append(mask)

    memo = {}

    def game(red_mask, blue_mask):
        state = (red_mask, blue_mask)
        if state in memo:
            return memo[state]

        rcount = bin(red_mask).count('1')
        bcount = bin(blue_mask).count('1')
        # 0 = Takahashi's turn, 1 = Aoki's turn
        turn = 0 if rcount == bcount else 1

        available = ~(red_mask | blue_mask) & 0x1FF

        # no moves left -> compare final scores
        if available == 0:
            t_score = sum(A[i] for i in range(9) if (red_mask >> i) & 1)
            a_score = sum(A[i] for i in range(9) if (blue_mask >> i) & 1)
            return 1 if t_score > a_score else -1

        if turn == 0:  # Takahashi
            # Check immediate winning moves
            for cell in range(9):
                if (available >> cell) & 1:
                    new_red = red_mask | (1 << cell)
                    for m in line_masks:
                        if (new_red & m) == m:
                            memo[state] = 1
                            return 1
            # Recursively try all moves
            for cell in range(9):
                if (available >> cell) & 1:
                    new_red = red_mask | (1 << cell)
                    if game(new_red, blue_mask) == 1:
                        memo[state] = 1
                        return 1
            memo[state] = -1
            return -1
        else:  # Aoki
            # Check immediate winning moves
            for cell in range(9):
                if (available >> cell) & 1:
                    new_blue = blue_mask | (1 << cell)
                    for m in line_masks:
                        if (new_blue & m) == m:
                            memo[state] = -1
                            return -1
            # Recursively try all moves
            for cell in range(9):
                if (available >> cell) & 1:
                    new_blue = blue_mask | (1 << cell)
                    if game(red_mask, new_blue) == -1:
                        memo[state] = -1
                        return -1
            memo[state] = 1
            return 1

    winner = game(0, 0)
    print("Takahashi" if winner == 1 else "Aoki")
