def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs (i, j) satisfy the divisibility condition
    divisible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                    divisible[i][j] = True

    # dp[mask][last]: number of ways to form a permutation using the elements
    # indicated by 'mask', ending with the element at index 'last'
    dp = [[0] * n for _ in range(1 << n)]

    # Base cases: permutations of length 1
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate over all masks (visited subsets)
    for mask in range(1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            ways = dp[mask][last]
            if ways == 0:
                continue
            # Try to extend the permutation with a new element 'nxt'
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if divisible[last][nxt]:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + ways) % MOD

    # Sum all permutations that use all elements
    full_mask = (1 << n) - 1
    ans = 0
    for i in range(n):
        ans = (ans + dp[full_mask][i]) % MOD
    return ans
