def minimumDeletions(word: str, k: int) -> int:
    # Count frequencies of each lowercase letter
    cnt = [0] * 26
    for ch in word:
        cnt[ord(ch) - ord('a')] += 1

    # Keep only non-zero frequencies
    freqs = [c for c in cnt if c > 0]
    if not freqs:
        return 0

    max_f = max(freqs)
    max_keep = 0

    # Try every possible minimum frequency L for the kept characters
    for L in range(1, max_f + 1):
        high = L + k
        total = 0
        for f in freqs:
            if f >= L:
                if f <= high:
                    total += f
                else:
                    total += high
        if total > max_keep:
            max_keep = total

    return len(word) - max_keep
