from functools import lru_cache

def max_possible_length(x: int, y: int, z: int) -> int:
    @lru_cache(maxsize=None)
    def dp(a: int, b: int, c: int, last: int) -> int:
        # last: 0 = start (nothing chosen yet)
        #       1 = last chosen was "AA"
        #       2 = last chosen was "BB"
        #       3 = last chosen was "AB"
        best = 0
        if last == 0:
            if a > 0:
                best = max(best, 1 + dp(a - 1, b, c, 1))
            if b > 0:
                best = max(best, 1 + dp(a, b - 1, c, 2))
            if c > 0:
                best = max(best, 1 + dp(a, b, c - 1, 3))
        elif last == 1:  # after "AA", only "BB" is allowed
            if b > 0:
                best = max(best, 1 + dp(a, b - 1, c, 2))
        elif last == 2:  # after "BB", "AA" or "AB" are allowed
            if a > 0:
                best = max(best, 1 + dp(a - 1, b, c, 1))
            if c > 0:
                best = max(best, 1 + dp(a, b, c - 1, 3))
        elif last == 3:  # after "AB", "AA" or "AB" are allowed
            if a > 0:
                best = max(best, 1 + dp(a - 1, b, c, 1))
            if c > 0:
                best = max(best, 1 + dp(a, b, c - 1, 3))
        return best

    max_strings = dp(x, y, z, 0)
    return 2 * max_strings
