def sum_of_power(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    # Only elements <= k can be part of a subset that sums to k
    valid_nums = [x for x in nums if x <= k]
    # dp[s][c] = number of subsets with sum s using exactly c elements
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for x in valid_nums:
        for s in range(k, x - 1, -1):
            for c in range(1, n + 1):
                if dp[s - x][c - 1]:
                    dp[s][c] = (dp[s][c] + dp[s - x][c - 1]) % MOD
    # Precompute powers of two
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD
    # Sum over all valid sizes
    ans = 0
    for c in range(n + 1):
        if dp[k][c]:
            ans = (ans + dp[k][c] * pow2[n - c]) % MOD
    return ans
