def numberOfRightTriangles(grid: list[list[int]]) -> int:
    m = len(grid)
    n = len(grid[0])
    row_ones = [0] * m
    col_ones = [0] * n

    # Count ones in each row and column
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                row_ones[r] += 1
                col_ones[c] += 1

    total = 0
    # For each 1, compute how many right triangles have it as the corner
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                total += (row_ones[r] - 1) * (col_ones[c] - 1)

    return total
