from functools import lru_cache

def waysToReachStair(k: int) -> int:
    @lru_cache(None)
    def dfs(i: int, jump: int, prev_down: bool) -> int:
        if i < 0:
            return 0
        ways = 0
        if i == k:
            ways += 1
        # Option 1: go down
        if not prev_down and i > 0:
            ways += dfs(i - 1, jump, True)
        # Option 2: go up by 2^jump
        ways += dfs(i + (1 << jump), jump + 1, False)
        return ways

    return dfs(1, 0, False)
```

