def solution(a, b, c):
    # Remove duplicates and strings that are substrings of others
    strings = [a, b, c]
    strings.sort(key=len, reverse=True)
    unique = []
    for s in strings:
        if not any(s in t for t in unique):
            unique.append(s)
    strings = unique

    if len(strings) == 1:
        return strings[0]

    n = len(strings)
    # Precompute overlaps
    overlap = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            s1 = strings[i]
            s2 = strings[j]
            max_k = min(len(s1), len(s2))
            for k in range(max_k, 0, -1):
                if s1[-k:] == s2[:k]:
                    overlap[i][j] = k
                    break

    # DP over subsets, dp[mask][i] = best superstring for mask ending with strings[i]
    dp = [[None] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = strings[i]

    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            cur = dp[mask][last]
            if cur is None:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                new_mask = mask | (1 << nxt)
                o = overlap[last][nxt]
                new_str = cur + strings[nxt][o:]
                old = dp[new_mask][nxt]
                if old is None or len(new_str) < len(old) or (len(new_str) == len(old) and new_str < old):
                    dp[new_mask][nxt] = new_str

    full = (1 << n) - 1
    best = None
    for i in range(n):
        s = dp[full][i]
        if s is not None:
            if best is None or len(s) < len(best) or (len(s) == len(best) and s < best):
                best = s
    return best
```

