def minimumBeautifulSubstrings(s: str) -> int:
    # Precompute all binary representations of powers of 5 up to length 15
    beautiful = set()
    power = 1
    while len(bin(power)) - 2 <= 15:
        beautiful.add(bin(power)[2:])
        power *= 5

    n = len(s)
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            # Leading zero check
            if s[j] == '0':
                continue
            if s[j:i] in beautiful:
                if dp[j] + 1 < dp[i]:
                    dp[i] = dp[j] + 1

    return dp[n] if dp[n] != INF else -1
