def can_split(nums, m):
    n = len(nums)
    if n == 1:
        return True

    # prefix sums for O(1) range sum queries
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # dp[i][j] = True if subarray nums[i..j] can be fully split
    dp = [[False] * n for _ in range(n)]

    # Base case: length 1 subarrays are already fully split
    for i in range(n):
        dp[i][i] = True

    # Consider subarrays of increasing length
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            # Try all possible split points
            for k in range(i, j):
                if dp[i][k] and dp[k + 1][j]:
                    left_ok = (k - i + 1 == 1) or (prefix[k + 1] - prefix[i] >= m)
                    right_ok = (j - k == 1) or (prefix[j + 1] - prefix[k + 1] >= m)
                    if left_ok and right_ok:
                        dp[i][j] = True
                        break

    return dp[0][n - 1]
