from typing import List
from collections import defaultdict

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        # Group indices by their values
        positions = defaultdict(list)
        for i, val in enumerate(nums):
            positions[val].append(i)

        # If all elements are the same, we need 0 seconds
        if len(positions) == 1:
            return 0

        # Initialize the answer with an upper bound (ceiling of half the maximum possible gap)
        ans = n

        for idx_list in positions.values():
            # A value with a single occurrence must spread to the whole circle
            if len(idx_list) == 1:
                max_gap = n - 1
            else:
                max_gap = 0
                m = len(idx_list)
                # Check gaps between consecutive occurrences, including the wrap-around gap
                for i in range(m):
                    if i == m - 1:
                        # Wrap-around gap
                        gap = idx_list[0] + n - idx_list[i] - 1
                    else:
                        gap = idx_list[i + 1] - idx_list[i] - 1
                    if gap > max_gap:
                        max_gap = gap

            # The time for this value is half of the longest gap (ceiling division)
            time = (max_gap + 1) // 2
            if time < ans:
                ans = time

        return ans
